  const tags = yield* createManagedTags(id, news.tags);

  yield* retryConcurrent(
    cloudwatch.putAlarmMuteRule({
      ...news,
      Name: name,
      Tags: Object.entries(tags).map(([Key, Value]) => ({
        Key,
        Value,
      })),
    }),
  );

